from decimal import Decimal
import sys
sys.path.insert(0, '.')
from billing import refund, GatewayError


class FakeGateway:
    def __init__(self, fail=False):
        self.fail = fail
        self.calls = []

    def refund(self, ref, amount):
        if self.fail:
            raise GatewayError('declined')
        self.calls.append(('refund', ref, amount))


def test_refund_amount_one_succeeds():
    gw = FakeGateway()
    result = refund(gw, 'ch_1', Decimal('1'))
    assert result == {'ok': True, 'ref': 'ch_1', 'amount': Decimal('1')}
